processPrePosts.script:
if (!!tw.local.sqlResults[0] && tw.local.sqlResults[0].rows.listLength > 0) {

		tw.local.transactionID = tw.local.sqlResults[0].rows[0].data[0];
	    
	}
else{
	//transaction isn't saved in database yet
		if(tw.local.transaction.remove){
			tw.local.end = true;
			tw.local.results = tw.local.transaction;
		}
		else
			tw.local.end = false;
}

TWComponent.script:
tw.local.transaction = new tw.object.FCTransactions();
var parsedData = JSON.parse(tw.local.data);


tw.local.transaction.accountNo = parsedData.accountNo;
tw.local.transaction.allocatedAmountInRequestCurrency = parsedData.allocatedAmountInRequestCurrency;
tw.local.transaction.amountAllocatedForCurrencyRequest = parsedData.amountAllocatedForCurrencyRequest;
tw.local.transaction.postingDate = new Date(parsedData.postingDate);
tw.local.transaction.referenceNumber = parsedData.referenceNumber;
tw.local.transaction.requestID =parsedData.requestID;
tw.local.transaction.transactionAmount = parsedData.transactionAmount;
tw.local.transaction.existAmount = parsedData.existAmount;
tw.local.transaction.valueDate = new Date(parsedData.valueDate);
tw.local.transaction.remove = parsedData.remove;
tw.local.transaction.previousAmount = parsedData.previousAmount;

tw.local.sqlStatement = new tw.object.SQLStatement();	
tw.local.sqlStatement.sql = "SELECT ID FROM "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST( POSTINGDATE AS DATE) = CAST ( ? AS DATE);"
tw.local.sqlStatement.parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStatement.parameters[0] = new tw.object.SQLParameter();
tw.local.sqlStatement.parameters[0].value = tw.local.transaction.referenceNumber;
tw.local.sqlStatement.parameters[1] = new tw.object.SQLParameter();
tw.local.sqlStatement.parameters[1].value = tw.local.transaction.postingDate;

tw.local.sqlStats = new tw.object.listOf.SQLStatement();

var ind =0;
tw.local.sqlStats[ind] = new tw.object.SQLStatement();
tw.local.sqlStats[ind].sql = "SELECT REQUESTID, COUNT(*) AS RequestCount FROM "+tw.env.LKP_DB_Schema+".ODC_SELECTEDTRANSACTIONS WHERE TRANSACTIONID = ? AND ISDELETED <> 'Yes' OR ISDELETED IS NULL GROUP BY REQUESTID;";
tw.local.sqlStats[ind].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStats[ind].parameters[0] = new tw.object.SQLParameter();
tw.local.sqlStats[ind++].parameters[0].value = tw.local.transactionID;

processPrePosts.script:
tw.local.results = new tw.object.FCTransactions();
tw.local.transaction.existAmount = tw.local.transaction.amountAllocatedForCurrencyRequest;
tw.local.results = tw.local.transaction;

